// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VW = 1120, VH = 412;
draw.viewbox(0, 0, VW, VH);
var root = draw.group();

var BLUE = '#2aa4d8', RED = '#e8554e', PINK = '#fce1d6', DARK = '#111';
var SERIF = 'Georgia, "Times New Roman", Times, serif';
var GRAY_FILL = '#efeae8', GRAY_STROKE = '#c6b8b4', GRAY_TXT = '#9b9b9b';

var state = { x: 0.7, overlay: false, focus: null };

/* ---------- small helpers ---------- */
function pts(a) { return a.map(function (p) { return p[0] + ',' + p[1]; }).join(' '); }

function txt(g, s, x, y, size, anchor, o) {
  o = o || {};
