  ['sin', '#f5b99f', 'inner triangle  =  sin x / 2']];
  for (var i = 0; i < 3; i++) {
    var k = items[i][0], yy = 126 + i * 32;
    var dim = (state.focus && state.focus !== k);
    g.rect(16, 16).move(856, yy - 12)
      .fill(dim ? GRAY_FILL : items[i][1])
      .stroke({ color: dim ? GRAY_STROKE : RED, width: 1.5 });
    txt(g, items[i][2], 880, yy + 2, 14, 'start',
      { fill: dim ? '#9b9b9b' : (state.focus === k ? '#c62828' : '#111'), halo: 3 });
  }
  txt(g, 'inner ⊂ sector ⊂ outer', ox + U / 2, 96, 15, 'middle', { fill: '#555', halo: 3, italic: true });
}

/* ---------- captions, formulas, readout ---------- */
function drawCaptions(g) {
  var keys = ['tan', 'sector', 'sin'];
  var labels = ['Area of triangle', 'Area of sector', 'Area of triangle'];
  var nums = ['tan x', 'x', 'sin x'];
  for (var i = 0; i < 3; i++) {
    (function (i) {
      var k = keys[i], foc = (state.focus === k), dim = (state.focus && !foc);
      var col = foc ? '#c62828' : (dim ? '#9b9b9b' : '#111');
      var fs = foc ? 18.5 : 16.5;
      var gg = g.group();
      gg.rect(170, 92).move(CEN[i] - 85, 286).fill(foc ? '#fdeceb' : '#fff').opacity(foc ? 1 : 0.01);
      txt(gg, labels[i], CEN[i], 304, fs, 'middle', { fill: col, weight: foc ? 'bold' : 'normal' });
      txt(gg, nums[i], CEN[i], 340, fs, 'middle', { fill: col, italic: (i === 1) });
      var hw = foc ? 32 : 27;
      gg.line(CEN[i] - hw, 347, CEN[i] + hw, 347).stroke({ color: col, width: 1.5 });
      txt(gg, '2', CEN[i], 368, fs, 'middle', { fill: col });
      gg.css('cursor', 'pointer');
      gg.on('mousemove', function (e) { showTooltip(TIP[k], e); }).on('mouseleave', hideTooltip);
      gg.on('click', function () {
        state.focus = foc ? null : k;
        showPopup(POP[k][0], POP[k][1]);
        render();
      });
    })(i);
  }
  txt(g, '≥', 640, 304, 19, 'middle');
  txt(g, '≥', 856, 304, 19, 'middle');
  txt(g, '≥', 640, 354, 19, 'middle');
  txt(g, '≥', 856, 354, 19, 'middle');
}

function drawReadout(g) {
  var x = state.x, A1 = Math.tan(x) / 2, A2 = x / 2, A3 = Math.sin(x) / 2;
  var c = Math.cos(x), r = Math.sin(x) / x;
  txt(g, 'tan x/2 = ' + A1.toFixed(3) + '    ≥    x/2 = ' + A2.toFixed(3) + '    ≥    sin x/2 = ' + A3.toFixed(3),
    740, 390, 13.5, 'middle', { fill: '#333' });
  txt(g, 'cos x = ' + c.toFixed(4) + '   ≤   sin x / x = ' + r.toFixed(4) + '   ≤   1/cos x = ' + (1 / c).toFixed(4),
    740, 408, 13.5, 'middle', { fill: '#b03028' });
  var lv = document.getElementById('liveVals');
  if (lv) {
    lv.innerHTML = 'tan x/2 = <b>' + A1.toFixed(4) + '</b><br>x/2 = <b>' + A2.toFixed(4) +
      '</b><br>sin x/2 = <b>' + A3.toFixed(4) + '</b><br>' +
      'cos x = ' + c.toFixed(4) + ' ≤ <b>sin x/x = ' + r.toFixed(4) + '</b> ≤ ' + (1 / c).toFixed(4);
  }
}

/* ---------- render ---------- */
function render() {
  root.clear();
  drawLeft(root.group());
  if (state.overlay) drawOverlay(root.group()); else drawRow(root.group());
  drawCaptions(root.group());
  drawReadout(root.group());
}

/* ---------- controls ---------- */
function setX(v) {
  v = Math.max(0.05, Math.min(1.4, v));
  state.x = v;
  var inp = document.getElementById('angleXInput');
  if (inp) inp.value = v;
  var out = document.getElementById('angleXVal');
  if (out) out.value = v.toFixed(2);
  render();
}
function update_angleX(v) { stopAnim(); state.x = v; render(); }
function toggle_overlayMode(on) { state.overlay = !!on; render(); }
function clearFocus() { state.focus = null; render(); }

var anim = { on: false, raf: 0, last: 0 };
function stopAnim() {
  anim.on = false;
  if (anim.raf) cancelAnimationFrame(anim.raf);
  anim.raf = 0;
  var b = document.getElementById('squeezePlayInput');
  if (b) { b.textContent = '▶ Let x → 0'; b.classList.remove('active'); }
}
function trigger_squeezePlay() {
  if (anim.on) { stopAnim(); return; }
  anim.on = true;
  anim.last = performance.now();
  var b = document.getElementById('squeezePlayInput');
  if (b) { b.textContent = '❚❚ Pause'; b.classList.add('active'); }
  if (state.x < 0.12) setX(1.3);
  function frame(now) {
    if (!anim.on) return;
    now = now || performance.now();
    var dt = Math.min(0.06, (now - anim.last) / 1000);
    anim.last = now;
    var nx = state.x * Math.pow(0.32, dt);
    if (nx < 0.06) nx = 1.3;
    setX(nx);
    anim.raf = requestAnimationFrame(frame);
  }
  anim.raf = requestAnimationFrame(frame);
}

/* ---------- demo steps ---------- */
var STEPS = [
  { title: 'The unit circle setup', narration: 'A single angle x produces three key points: (1,0) on the axis, (cos x, sin x) on the circle, and (1, tan x) on the tangent line. Drag the slider to see all three move together.', state: { angleX: 0.7, overlayMode: 'Side by side' } },
  { title: 'Three regions, three areas', narration: 'The same angle defines a big triangle of area tan x/2, a sector of area x/2, and a small triangle of area sin x/2. Click any caption to highlight its region and formula.', state: { angleX: 0.7, overlayMode: 'Side by side' } },
  { title: 'Nesting makes the order obvious', narration: 'Overlay the three regions: the small triangle sits inside the sector, which sits inside the big triangle. Containment forces sin x/2 ≤ x/2 ≤ tan x/2.', state: { angleX: 0.7, overlayMode: 'Overlaid' } },
  { title: 'Shrinking the angle', narration: 'Reduce x and the three nested regions become nearly indistinguishable — their areas crowd together.', state: { angleX: 0.25, overlayMode: 'Overlaid' } },
  { title: 'The squeeze', narration: 'Dividing the inequality by sin x/2 gives cos x ≤ sin x/x ≤ 1/cos x. As x → 0 both bounds go to 1, so sin x / x must go to 1.', state: { angleX: 0.08, overlayMode: 'Overlaid' } }
];
var stepIdx = 0;
function applyStep(i) {
  stopAnim();
  stepIdx = (i + STEPS.length) % STEPS.length;
  var s = STEPS[stepIdx];
  state.x = +s.state.angleX;
  state.overlay = (s.state.overlayMode === 'Overlaid');
  state.focus = null;
  var inp = document.getElementById('angleXInput');
  if (inp) inp.value = state.x;
  var out = document.getElementById('angleXVal');
  if (out) out.value = state.x.toFixed(2);
  var cb = document.getElementById('overlayModeInput');
  if (cb) cb.checked = state.overlay;
  var n = document.getElementById('demoNarration');
  if (n) n.textContent = s.narration;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (stepIdx + 1) + '/' + STEPS.length + ' · ' + s.title;
  render();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

