function arcSeg(cx, cy, r, a1, a2) {
  var x2 = cx + r * Math.cos(a2), y2 = cy - r * Math.sin(a2);
  var large = Math.abs(a2 - a1) > Math.PI ? 1 : 0;
  var sweep = (a2 > a1) ? 0 : 1;
  return 'A' + r + ',' + r + ' 0 ' + large + ',' + sweep + ' ' + x2 + ',' + y2;
}

function arcPath(cx, cy, r, a1, a2) {
  return 'M' + (cx + r * Math.cos(a1)) + ',' + (cy - r * Math.sin(a1)) + ' ' + arcSeg(cx, cy, r, a1, a2);
