  var d = 'M' + x1 + ',' + y + ' q0,' + h + ' ' + h + ',' + h + ' H' + (mid - h) +
    ' q' + h + ',0 ' + h + ',' + h + ' q0,' + (-h) + ' ' + h + ',' + (-h) +
    ' H' + (x2 - h) + ' q' + h + ',0 ' + h + ',' + (-h);
