// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VW = 900, VH = 344;
draw.viewbox(0, 0, VW, VH);
var root = draw.group();

var BLUE = '#29a3dc', RED = '#ea6a60', RED_D = '#e04a3f', PINK = '#fce0d5', DARK = '#111';
var SERIF = 'Georgia, "Times New Roman", Times, serif';
var GRAY_FILL = '#eeeaea', GRAY_STROKE = '#c3b6b4', GRAY_TXT = '#9c9c9c';

var state = { x: 0.7, overlay: false, focus: null };

/* ---------- helpers ---------- */
function pts(a) {
  return a.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
}

function txt(g, s, tx, ty, size, anchor, o) {
  o = o || {};
  var t = g.text(s);
  t.font({
    family: SERIF, size: size, anchor: anchor || 'start',
    style: o.italic ? 'italic' : 'normal', weight: o.weight || 'normal'
  });
  t.attr({ x: tx, y: ty });
  t.each(function () { this.attr('x', tx); });
  t.fill(o.fill || DARK);
  if (o.halo) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
  }
  return t;
}

function arcSeg(cx, cy, r, a1, a2) {
  var x2 = cx + r * Math.cos(a2), y2 = cy - r * Math.sin(a2);
  var large = Math.abs(a2 - a1) > Math.PI ? 1 : 0;
  var sweep = (a2 > a1) ? 0 : 1;
  return 'A' + r + ',' + r + ' 0 ' + large + ',' + sweep + ' ' + x2 + ',' + y2;
}

function arcPath(cx, cy, r, a1, a2) {
  return 'M' + (cx + r * Math.cos(a1)) + ',' + (cy - r * Math.sin(a1)) + ' ' + arcSeg(cx, cy, r, a1, a2);
}

function headPoly(g, x, y, a, s, color) {
  return g.polygon(pts([
    [x, y],
    [x - s * Math.cos(a - 0.38), y - s * Math.sin(a - 0.38)],
    [x - s * Math.cos(a + 0.38), y - s * Math.sin(a + 0.38)]
  ])).fill(color).stroke('none');
}

function arrowLine(g, x1, y1, x2, y2, color, w, s) {
  var a = Math.atan2(y2 - y1, x2 - x1);
  g.line(x1, y1, x2 - s * 0.55 * Math.cos(a), y2 - s * 0.55 * Math.sin(a)).stroke({ color: color, width: w });
  headPoly(g, x2, y2, a, s, color);
}

function braceH(g, x1, x2, y, h) {
  var mid = (x1 + x2) / 2;
  var d = 'M' + x1 + ',' + y + ' q0,' + h + ' ' + h + ',' + h + ' H' + (mid - h) +
    ' q' + h + ',0 ' + h + ',' + h + ' q0,' + (-h) + ' ' + h + ',' + (-h) +
    ' H' + (x2 - h) + ' q' + h + ',0 ' + h + ',' + (-h);
  return g.path(d).fill('none').stroke({ color: '#111', width: 1.3, linejoin: 'round' });
}

function braceV(g, y1, y2, x, h) {
  var mid = (y1 + y2) / 2;
  var d = 'M' + x + ',' + y1 + ' q' + h + ',0 ' + h + ',' + h + ' V' + (mid - h) +
    ' q0,' + h + ' ' + h + ',' + h + ' q' + (-h) + ',0 ' + (-h) + ',' + h +
    ' V' + (y2 - h) + ' q0,' + h + ' ' + (-h) + ',' + h;
  return g.path(d).fill('none').stroke({ color: '#111', width: 1.3, linejoin: 'round' });
}

function angleMark(g, cx, cy, ang, r, labelR, size) {
  g.path(arcPath(cx, cy, r, 0.12, ang)).fill('none').stroke({ color: '#222', width: 1.3 });
  var ex = cx + r * Math.cos(ang), ey = cy - r * Math.sin(ang);
  headPoly(g, ex, ey, Math.atan2(-Math.cos(ang), -Math.sin(ang)), 6, '#222');
  var la = ang * 0.5;
  txt(g, 'x', cx + labelR * Math.cos(la), cy - labelR * Math.sin(la) + size * 0.34,
    size, 'middle', { italic: true, halo: 3 });
}

/* ---------- focus behaviour ---------- */
var TIP = {
  tan: 'Outer triangle — area = tan x / 2',
  sector: 'Circular sector — area = x / 2',
  sin: 'Inner triangle — area = sin x / 2'
};
var POP = {
  tan: ['Outer triangle: tan x / 2',
    'Its base is the radius 1 and its height is the tangent length tan x, so the area is tan x / 2. The sector fits entirely inside it, which forces x / 2 \u2264 tan x / 2.'],
  sector: ['Circular sector: x / 2',
    'A sector of the unit circle with angle x is the fraction x / 2\u03c0 of a disc of area \u03c0, so its area is exactly x / 2. It is trapped between the two triangles.'],
  sin: ['Inner triangle: sin x / 2',
    'Its base is 1 and its height is sin x, the vertical drop from the circle point, so the area is sin x / 2. It fits inside the sector, so sin x / 2 \u2264 x / 2.']
};

function fillFor(key, base) { return (state.focus && state.focus !== key) ? GRAY_FILL : base; }
function strokeFor(key) {
  if (state.focus === key) return { color: '#c62828', width: 3, linejoin: 'round' };
  if (state.focus) return { color: GRAY_STROKE, width: 1.4, linejoin: 'round' };
  return { color: RED, width: 2, linejoin: 'round' };
}
function arcCol(key) { return (state.focus && state.focus !== key) ? '#bcc8cd' : BLUE; }

function region(shape, key) {
  shape.css('cursor', 'pointer');
  shape.on('mousemove', function (e) { showTooltip(TIP[key], e); });
  shape.on('mouseleave', hideTooltip);
  shape.on('click', function () {
    state.focus = (state.focus === key) ? null : key;
    if (state.focus) showPopup(POP[key][0], POP[key][1]); else hidePopup();
    render();
  });
  return shape;
}

/* ---------- LEFT PANEL ---------- */
var OX = 150, OY = 162, R = 92;

function drawLeft(g) {
  var x = state.x, co = Math.cos(x), si = Math.sin(x), ta = Math.tan(x);

  arrowLine(g, 10, OY, 322, OY, '#111', 1.6, 10);
  arrowLine(g, OX, 334, OX, 8, '#111', 1.6, 10);

  g.circle(2 * R).center(OX, OY).fill('none').stroke({ color: BLUE, width: 2.6 });

  var px = OX + R * co, py = OY - R * si;
  var tyRaw = OY - R * ta;
  var clipped = tyRaw < 26;
  var ty = clipped ? 26 : tyRaw;
  var L = clipped ? (OY - 26) / si : R / co;

  g.line(OX, OY, OX + R, OY).stroke({ color: '#5d2b26', width: 2.2 });
  g.line(OX, OY, OX + L * co, OY - L * si).stroke({ color: RED, width: 1.9 });
  g.line(OX + R, OY, OX + R, ty).stroke({ color: RED, width: 1.9 }).attr('stroke-dasharray', '7,4');
  g.line(px, py, OX + R, OY).stroke({ color: RED, width: 1.9 }).attr('stroke-dasharray', '7,4');
  g.path(arcPath(OX, OY, R, 0, x)).fill('none').stroke({ color: BLUE, width: 4.2, linecap: 'round' });

  var d1 = g.circle(9).center(OX + R, OY).fill(RED_D).css('cursor', 'pointer');
  d1.on('mousemove', function (e) { showTooltip('(1, 0) — foot of the unit radius', e); }).on('mouseleave', hideTooltip);
  var d2 = g.circle(9).center(px, py).fill(RED_D).css('cursor', 'pointer');
  d2.on('mousemove', function (e) {
    showTooltip('(cos x, sin x) = (' + co.toFixed(3) + ', ' + si.toFixed(3) + ')', e);
  }).on('mouseleave', hideTooltip);
  if (!clipped) {
    var d3 = g.circle(9).center(OX + R, ty).fill(RED_D).css('cursor', 'pointer');
    d3.on('mousemove', function (e) {
      showTooltip('(1, tan x),  tan x = ' + ta.toFixed(3), e);
    }).on('mouseleave', hideTooltip);
  }

  angleMark(g, OX, OY, x, 28, 45, 17);
  braceH(g, OX, OX + R, OY + 11, 6);
  txt(g, '1', OX + R / 2, OY + 41, 17, 'middle', { halo: 3 });

  /* point labels — placed in open space, no leader clutter */
  var labelY = clipped ? 22 : Math.min(ty - 13, OY - 32);
  txt(g, '(1, tan x)', OX + R, labelY, 16.5, 'middle', { halo: 3.5 });
  txt(g, '(1, 0)', OX + R + 13, OY - 10, 16.5, 'start', { halo: 3.5 });
  txt(g, '(cos x, sin x)', 256, 116, 16.5, 'start', { halo: 3.5 });
  arrowLine(g, 252, 111, px + 8, py - 5, '#111', 1.2, 7.5);
}

/* ---------- RIGHT PANEL — side by side ---------- */
var CEN = [425, 605, 780], YB = 162;

function drawRow(g) {
  var x = state.x, t = Math.tan(x), s = Math.sin(x), co = Math.cos(x);
  var u = Math.min(110, 140 / Math.max(t, 1e-6));
  var ar = Math.min(24, u * 0.26), lr = Math.min(38, u * 0.44);
  var fs = Math.max(13, Math.min(16, u * 0.15));

  /* A — outer triangle */
  var a0 = CEN[0] - u / 2;
  region(g.polygon(pts([[a0, YB], [a0 + u, YB], [a0 + u, YB - u * t]]))
    .fill(fillFor('tan', PINK)).stroke(strokeFor('tan')), 'tan');
  g.path(arcPath(a0, YB, u, 0, x)).fill('none')
    .stroke({ color: arcCol('tan'), width: 2.4 }).attr('stroke-dasharray', '8,5');
  txt(g, 'tan x', a0 + u + 10, YB - u * t / 2 + 6, 17, 'start', { halo: 3.5 });
  txt(g, '1', CEN[0], YB + 24, 17, 'middle', { halo: 3 });
  angleMark(g, a0, YB, x, ar, lr, fs);

  /* B — sector */
  var a1 = CEN[1] - u / 2;
  region(g.path('M' + a1 + ',' + YB + ' L' + (a1 + u) + ',' + YB + ' ' + arcSeg(a1, YB, u, 0, x) + ' Z')
    .fill(fillFor('sector', PINK)).stroke(strokeFor('sector')), 'sector');
  g.path(arcPath(a1, YB, u, 0, x)).fill('none').stroke({ color: arcCol('sector'), width: 3.2 });
  txt(g, '1', CEN[1], YB + 24, 17, 'middle', { halo: 3 });
  angleMark(g, a1, YB, x, ar, lr, fs);

  /* C — inner triangle */
  var a2 = CEN[2] - u / 2, cx2 = a2 + u * co, cy2 = YB - u * s;
  region(g.polygon(pts([[a2, YB], [a2 + u, YB], [cx2, cy2]]))
    .fill(fillFor('sin', PINK)).stroke(strokeFor('sin')), 'sin');
  g.path(arcPath(a2, YB, u, 0, x)).fill('none')
    .stroke({ color: arcCol('sin'), width: 2.4 }).attr('stroke-dasharray', '8,5');
  g.line(cx2, cy2, cx2, YB).stroke({ color: RED, width: 1.2 }).attr('stroke-dasharray', '4,3');
  txt(g, '1', CEN[2], YB + 24, 17, 'middle', { halo: 3 });
  angleMark(g, a2, YB, x, ar, lr, fs);
  var bx = a2 + u + 8;
  g.line(cx2, cy2, bx, cy2).stroke({ color: '#111', width: 0.9 });
  braceV(g, cy2, YB, bx, 5);
  txt(g, 'sin x', bx + 15, (cy2 + YB) / 2 + 6, 16.5, 'start', { halo: 3.5 });
}

/* ---------- RIGHT PANEL — overlaid (nested) ---------- */
function drawOverlay(g) {
  var x = state.x, t = Math.tan(x), s = Math.sin(x), co = Math.cos(x);
  var U = Math.min(150, 132 / Math.max(t, 1e-6));
  var ox = 420, oy = YB;

  region(g.polygon(pts([[ox, oy], [ox + U, oy], [ox + U, oy - U * t]]))
    .fill(fillFor('tan', '#fdeade')).stroke(strokeFor('tan')), 'tan');
  region(g.path('M' + ox + ',' + oy + ' L' + (ox + U) + ',' + oy + ' ' + arcSeg(ox, oy, U, 0, x) + ' Z')
    .fill(fillFor('sector', '#fbd2ba')).stroke(strokeFor('sector')), 'sector');
  var cx2 = ox + U * co, cy2 = oy - U * s;
  region(g.polygon(pts([[ox, oy], [ox + U, oy], [cx2, cy2]]))
    .fill(fillFor('sin', '#f4b299')).stroke(strokeFor('sin')), 'sin');

  g.path(arcPath(ox, oy, U, 0, x)).fill('none').stroke({ color: arcCol('sector'), width: 3.2 });
  g.line(cx2, cy2, cx2, oy).stroke({ color: '#b03028', width: 1.1 }).attr('stroke-dasharray', '4,3');
  txt(g, 'sin x', cx2 - 8, (cy2 + oy) / 2 + 5, 15.5, 'end', { halo: 3.5 });
  txt(g, 'tan x', ox + U + 9, oy - U * t / 2 + 5, 15.5, 'start', { halo: 3.5 });
  angleMark(g, ox, oy, x, 26, 42, 16);
  txt(g, '1', ox + U / 2, oy + 24, 17, 'middle', { halo: 3 });

  var items = [
    ['tan', '#fdeade', 'outer triangle  =  tan x / 2'],
    ['sector', '#fbd2ba', 'sector  =  x / 2'],
    ['sin', '#f4b299', 'inner triangle  =  sin x / 2']
  ];
  for (var i = 0; i < 3; i++) {
    var k = items[i][0], yy = 52 + i * 28;
    var dim = (state.focus && state.focus !== k);
    g.rect(15, 15).move(646, yy - 11)
      .fill(dim ? GRAY_FILL : items[i][1])
      .stroke({ color: dim ? GRAY_STROKE : RED, width: 1.4 });
    txt(g, items[i][2], 668, yy + 2, 15, 'start',
      { fill: dim ? GRAY_TXT : (state.focus === k ? '#c62828' : '#111'), halo: 3 });
  }
  txt(g, 'inner \u2282 sector \u2282 outer', 646, 152, 15.5, 'start', { fill: '#555', italic: true, halo: 3 });
}

/* ---------- captions + formulas ---------- */
function drawCaptions(g) {
  var keys = ['tan', 'sector', 'sin'];
  var labels = ['Area of triangle', 'Area of sector', 'Area of triangle'];
  var nums = ['tan x', 'x', 'sin x'];
  for (var i = 0; i < 3; i++) {
    (function (i) {
      var k = keys[i];
      var foc = (state.focus === k);
      var dim = (state.focus && !foc);
      var col = foc ? '#c62828' : (dim ? GRAY_TXT : '#111');
      var fs = foc ? 20 : 18;
      var gg = g.group();
      gg.rect(184, 104).move(CEN[i] - 92, 208).radius(6)
        .fill(foc ? '#fdeceb' : '#ffffff').opacity(foc ? 1 : 0.01);
      txt(gg, labels[i], CEN[i], 232, fs, 'middle', { fill: col, weight: foc ? 'bold' : 'normal' });
      txt(gg, nums[i], CEN[i], 274, fs, 'middle', { fill: col, italic: (i === 1) });
      var hw = foc ? 32 : 27;
      gg.line(CEN[i] - hw, 282, CEN[i] + hw, 282).stroke({ color: col, width: 1.5 });
      txt(gg, '2', CEN[i], 304, fs, 'middle', { fill: col });
      gg.css('cursor', 'pointer');
      gg.on('mousemove', function (e) { showTooltip(TIP[k], e); }).on('mouseleave', hideTooltip);
      gg.on('click', function () {
        state.focus = foc ? null : k;
        if (state.focus) showPopup(POP[k][0], POP[k][1]); else hidePopup();
        render();
      });
    })(i);
  }
  txt(g, '\u2265', 515, 232, 20, 'middle');
  txt(g, '\u2265', 692, 232, 20, 'middle');
  txt(g, '\u2265', 515, 288, 20, 'middle');
  txt(g, '\u2265', 692, 288, 20, 'middle');
  txt(g, 'cos x  \u2264  sin x / x  \u2264  1 / cos x', 605, 331, 15.5, 'middle',
    { fill: '#b03028', italic: true });
}

/* ---------- side-panel numeric readout ---------- */
function updateReadout() {
  var x = state.x;
  var A1 = Math.tan(x) / 2, A2 = x / 2, A3 = Math.sin(x) / 2;
  var c = Math.cos(x), r = Math.sin(x) / x;
  var lv = document.getElementById('liveVals');
  if (lv) {
    lv.innerHTML = 'tan x/2 = <b>' + A1.toFixed(4) + '</b><br>' +
      'x/2 = <b>' + A2.toFixed(4) + '</b><br>' +
      'sin x/2 = <b>' + A3.toFixed(4) + '</b><br>' +
      'cos x = ' + c.toFixed(4) + ' \u2264 <b>sin x/x = ' + r.toFixed(4) +
      '</b> \u2264 ' + (1 / c).toFixed(4);
  }
}

/* ---------- render ---------- */
function render() {
  root.clear();
  drawLeft(root.group());
  if (state.overlay) { drawOverlay(root.group()); } else { drawRow(root.group()); }
  drawCaptions(root.group());
  updateReadout();
}

/* ---------- controls ---------- */
function syncSlider() {
  var inp = document.getElementById('angleXInput');
  if (inp) inp.value = state.x;
  var out = document.getElementById('angleXVal');
  if (out) out.value = state.x.toFixed(2);
}
function setX(v) {
  state.x = Math.max(0.05, Math.min(1.5, v));
  syncSlider();
  render();
}
function update_angleX(v) { stopAnim(); setX(v); }
function toggle_overlayMode(on) { state.overlay = !!on; render(); }
function clearFocus() { state.focus = null; hidePopup(); render(); }

/* ---------- x → 0 animation ---------- */
var anim = { on: false, raf: 0, last: 0 };
function stopAnim() {
  anim.on = false;
  if (anim.raf) cancelAnimationFrame(anim.raf);
  anim.raf = 0;
  var b = document.getElementById('squeezePlayInput');
  if (b) { b.textContent = '\u25b6 Let x \u2192 0'; b.classList.remove('active'); }
}
function trigger_squeezePlay() {
  if (anim.on) { stopAnim(); return; }
  anim.on = true;
  anim.last = (window.performance ? performance.now() : Date.now());
  var b = document.getElementById('squeezePlayInput');
  if (b) { b.textContent = '\u275a\u275a Pause'; b.classList.add('active'); }
  if (state.x < 0.12) setX(1.3);
  function frame(now) {
    if (!anim.on) return;
    now = now || (window.performance ? performance.now() : Date.now());
    var dt = Math.min(0.06, (now - anim.last) / 1000);
    anim.last = now;
    var nx = state.x * Math.pow(0.30, dt);
    if (nx < 0.06) nx = 1.3;
    setX(nx);
    anim.raf = requestAnimationFrame(frame);
  }
  anim.raf = requestAnimationFrame(frame);
}

