    state: { angleX: 0.08, overlayMode: 'Overlaid' }
  }
];
var stepIdx = 0;

function applyStep(i) {
  stopAnim();
  hidePopup();
  stepIdx = (i + STEPS.length) % STEPS.length;
  var s = STEPS[stepIdx];
